def transform(grid):
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next((v for v in counts if v != bg), None)
    out = [row[:] for row in grid]
    if fg is None:
        return out
    comp = [[-1] * w for _ in range(h)]
    n = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != fg or comp[r][c] >= 0:
                continue
            q = deque([(r, c)])
            comp[r][c] = n
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == fg and comp[yy][xx] < 0:
                        comp[yy][xx] = n
                        q.append((yy, xx))
            n += 1
    edges = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != fg:
                continue
            for dr, dc in ((0, 1), (1, 0)):
                rr, cc = r + dr, c + dc
                while rr < h and cc < w and grid[rr][cc] == bg:
                    rr += dr
                    cc += dc
                if rr < h and cc < w and grid[rr][cc] == fg and comp[r][c] != comp[rr][cc]:
                    cells = []
                    y, x = r + dr, c + dc
                    while (y, x) != (rr, cc):
                        cells.append((y, x))
                        y += dr
                        x += dc
                    # Prefer horizontal gaps when equal length.
                    edges.append((len(cells), 0 if dr == 0 else 1, r, c, rr, cc, comp[r][c], comp[rr][cc], cells))
    parent = list(range(n))
    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a
    for edge in sorted(edges):
        length, orient, r, c, rr, cc, a, b, cells = edge
        a, b = find(a), find(b)
        if a != b:
            parent[a] = b
            for y, x in cells:
                out[y][x] = 2
    return out
